const RW = 0.38, RG = 0.40, RING = 0.07, ER = 0.045;
const STUB_X = 3.0, STUB_Z = 1.9;
const C_BLACK = 0x000000, C_ACCENT = 0x1a6fd4, C_DIM = 0xcccccc;
const C_WHITE = 0xffffff, C_GRAY = 0x8c8c8c;

