// @FIGURE_CODE_BEGIN
// ── Element spec ───────────────────────────────────────────────────────────
// white x node fill     → CircleGeometry(0.38)            fill #FFFFFF (shaded), billboarded
// white x node outline  → RingGeometry(0.38, 0.45)        black, billboarded
// gray  y node fill     → CircleGeometry(0.40)            fill #8C8C8C (shaded), billboarded
// gray  y node outline  → RingGeometry(0.40, 0.47)        black, billboarded
// intra-row edge        → CylinderGeometry(r=0.045) black  (i,j)->(i+1,j)
// right frame stub      → CylinderGeometry(r=0.045) black  (2,j)-> +3.0 in X (runs off frame)
// inter-row diagonal    → CylinderGeometry(r=0.045) black  (i,j)->(i,j-1)
// front frame stub      → CylinderGeometry(r=0.045) black  (i,0)-> +1.9 in Z (off lower-left)
// observation link      → CylinderGeometry(r=0.045) black  white node -> gray node
// labels x1..x3,y1..y3  → addLabel, bold serif with <sub>, up-and-right of back-row nodes

const SPACING = 2.6;          // site spacing in X and in Z
const GY = 1.9, GZ = -0.35;   // observation node: +1.9 in Y, slightly behind in Z
const RW = 0.38, RG = 0.40, RING = 0.07, ER = 0.045;
const STUB_X = 3.0, STUB_Z = 1.9;
const C_BLACK = 0x000000, C_ACCENT = 0x1a6fd4, C_DIM = 0xcccccc;
const C_WHITE = 0xffffff, C_GRAY = 0x8c8c8c;

// Oblique shear (camera does it): screen = (x - cx*z, y - cy*z), cx=cos54*0.68,
// cy=sin54*0.68. So LARGER z is drawn down-and-left = nearer the viewer.
// j = 0 front row (lowest-left), j = 2 back labelled row (highest-right).
const OBL_ANGLE = 54, OBL_SCALE = 0.68;

function sitePos(i, j) { return new THREE.Vector3((i - 1) * SPACING, 0, (1 - j) * SPACING); }
function grayPos(i, j) { const p = sitePos(i, j); return new THREE.Vector3(p.x, GY, p.z + GZ); }

const figRoot = new THREE.Group();
scene.add(figRoot);

const billboards = [];
const styled = [];          // { mesh, tc:THREE.Color, to:number }

function styleEntry(mesh) {
  const e = { mesh, tc: new THREE.Color(mesh.material.color.getHex()), to: 1 };
  styled.push(e);
  mesh.userData.style = e;
  return e;
}

function makeEdge(a, b) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const geo = new THREE.CylinderGeometry(ER, ER, len, 10, 1);
  const mat = new THREE.MeshBasicMaterial({
    color: C_BLACK, transparent: true, opacity: 1, depthTest: false, depthWrite: false
  });
  const m = new THREE.Mesh(geo, mat);
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  m.renderOrder = 1;
  figRoot.add(m);
  styleEntry(m);
  return m;
}

function makeDisc(pos, r, fillHex, orderFill) {
  const fmat = new THREE.MeshBasicMaterial({
    color: fillHex, transparent: true, opacity: 1, depthTest: false, depthWrite: false,
    side: THREE.DoubleSide
  });
  const fill = new THREE.Mesh(new THREE.CircleGeometry(r, 48), fmat);
  fill.position.copy(pos);
  fill.renderOrder = orderFill;
  figRoot.add(fill); billboards.push(fill); styleEntry(fill);

  const rmat = new THREE.MeshBasicMaterial({
    color: C_BLACK, transparent: true, opacity: 1, depthTest: false, depthWrite: false,
    side: THREE.DoubleSide
  });
  const ring = new THREE.Mesh(new THREE.RingGeometry(r, r + RING, 48), rmat);
  ring.position.copy(pos);
  ring.renderOrder = orderFill + 1;
  figRoot.add(ring); billboards.push(ring); styleEntry(ring);

  return { fill, ring };
}

/* ── edges ─────────────────────────────────────────────────────────────── */
const gridEdges = [];   // { mesh, sites:[[i,j],...] }
const obsEdges = [];    // { mesh, site:[i,j] }

// intra-row horizontals + right frame stubs
for (let j = 0; j < 3; j++) {
  for (let i = 0; i < 2; i++) {
    gridEdges.push({ mesh: makeEdge(sitePos(i, j), sitePos(i + 1, j)), sites: [[i, j], [i + 1, j]] });
  }
  const p = sitePos(2, j);
  gridEdges.push({ mesh: makeEdge(p, new THREE.Vector3(p.x + STUB_X, 0, p.z)), sites: [[2, j]] });
}
// inter-row diagonals (back row -> row in front) + front-row stubs off lower-left
for (let j = 1; j < 3; j++) {
  for (let i = 0; i < 3; i++) {
    gridEdges.push({ mesh: makeEdge(sitePos(i, j), sitePos(i, j - 1)), sites: [[i, j], [i, j - 1]] });
  }
}
for (let i = 0; i < 3; i++) {
  const p = sitePos(i, 0);
  gridEdges.push({ mesh: makeEdge(p, new THREE.Vector3(p.x, 0, p.z + STUB_Z)), sites: [[i, 0]] });
}
// vertical observation links
for (let j = 0; j < 3; j++) for (let i = 0; i < 3; i++) {
  obsEdges.push({ mesh: makeEdge(sitePos(i, j), grayPos(i, j)), site: [i, j] });
}

/* ── nodes ─────────────────────────────────────────────────────────────── */
const white = [], gray = [];
for (let j = 0; j < 3; j++) {
  white.push([]); gray.push([]);
  for (let i = 0; i < 3; i++) {
    const w = makeDisc(sitePos(i, j), RW, C_WHITE, 6);
    w.i = i; w.j = j; w.shade = new THREE.Color(C_WHITE);
    white[j].push(w);
    const g = makeDisc(grayPos(i, j), RG, C_GRAY, 4);
    g.i = i; g.j = j; g.shade = new THREE.Color(C_GRAY);
    gray[j].push(g);
  }
}

/* ── camera (oblique shear; pose is fixed front-on) ────────────────────── */
setCameraView({
  projection: 'oblique',
  obliqueAngleDeg: OBL_ANGLE,
  depthScale: OBL_SCALE,
  heightFraction: 0.88
});

/* ── labels (back row j = 2 only) ──────────────────────────────────────── */
const SER = (t) =>
  `<span style="font-family:Georgia,'Times New Roman',serif;font-weight:700;` +
  `text-shadow:0 0 4px #fff,0 0 4px #fff,0 0 4px #fff">${t}</span>`;

for (let i = 0; i < 3; i++) {
  const p = sitePos(i, 2);
  addLabel(SER(`x<sub>${i + 1}</sub>`), new THREE.Vector3(p.x + 0.40, p.y + 0.60, p.z), { fontSize: '28px' });
  const q = grayPos(i, 2);
  addLabel(SER(`y<sub>${i + 1}</sub>`), new THREE.Vector3(q.x + 0.36, q.y + 0.66, q.z), { fontSize: '28px' });
}

/* ── fixed pseudo-random per-site "observations" ───────────────────────── */
function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    let t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
const rnd = mulberry32(20240517);
const obs = [];
for (let j = 0; j < 3; j++) { obs.push([]); for (let i = 0; i < 3; i++) obs[j].push(rnd()); }

function smoothField(beta) {
  let s = obs.map(r => r.slice());
  for (let k = 0; k < 8; k++) {
    const ns = s.map(r => r.slice());
    for (let j = 0; j < 3; j++) for (let i = 0; i < 3; i++) {
      let sum = 0, n = 0;
      if (i > 0) { sum += s[j][i - 1]; n++; }
      if (i < 2) { sum += s[j][i + 1]; n++; }
      if (j > 0) { sum += s[j - 1][i]; n++; }
      if (j < 2) { sum += s[j + 1][i]; n++; }
      const mean = n ? sum / n : s[j][i];
      ns[j][i] = (1 - beta) * obs[j][i] + beta * mean;
    }
    s = ns;
  }
  return s;
}

const RAMP_W0 = new THREE.Color(0xffffff), RAMP_W1 = new THREE.Color(0x4d4d4d);
const RAMP_G0 = new THREE.Color(0xa8a8a8), RAMP_G1 = new THREE.Color(0x3c3c3c);
const BASE_W = new THREE.Color(C_WHITE), BASE_G = new THREE.Color(C_GRAY);

/* ── state ─────────────────────────────────────────────────────────────── */
const state = { layer: 'full', selected: null };
let beta = 0, betaTarget = 0;

function updateShading() {
  const s = smoothField(beta);
  const t = Math.min(1, beta / 0.1);
  for (let j = 0; j < 3; j++) for (let i = 0; i < 3; i++) {
    const rw = RAMP_W0.clone().lerp(RAMP_W1, s[j][i]);
    white[j][i].shade.copy(BASE_W).lerp(rw, t);
    const rg = RAMP_G0.clone().lerp(RAMP_G1, obs[j][i]);
    gray[j][i].shade.copy(BASE_G).lerp(rg, t);
  }
}

function neighbors(i, j) {
  const out = [];
  if (i > 0) out.push([i - 1, j]);
  if (i < 2) out.push([i + 1, j]);
  if (j > 0) out.push([i, j - 1]);
  if (j < 2) out.push([i, j + 1]);
  return out;
}

function set(e, hex, op) { e.tc.setHex(hex); e.to = op; }

function updateStyle() {
  const showGrid = state.layer !== 'obs';
  const showObs = state.layer !== 'lattice';
  const sel = state.selected;
  const nb = sel ? neighbors(sel[0], sel[1]) : [];
  const isNb = (i, j) => nb.some(n => n[0] === i && n[1] === j);
  const isSel = (i, j) => sel && sel[0] === i && sel[1] === j;

  for (const e of gridEdges) {
    const st = e.mesh.userData.style;
    if (!showGrid) { set(st, C_BLACK, 0); continue; }
    if (!sel) { set(st, C_BLACK, 1); continue; }
    const inc = e.sites.some(s => s[0] === sel[0] && s[1] === sel[1]);
    inc ? set(st, C_ACCENT, 1) : set(st, C_DIM, 0.15);
  }
  for (const e of obsEdges) {
    const st = e.mesh.userData.style;
    if (!showObs) { set(st, C_BLACK, 0); continue; }
    if (!sel) { set(st, C_BLACK, 1); continue; }
    isSel(e.site[0], e.site[1]) ? set(st, C_ACCENT, 1) : set(st, C_DIM, 0.15);
  }
  for (let j = 0; j < 3; j++) for (let i = 0; i < 3; i++) {
    const w = white[j][i];
    const inBl = !sel || isSel(i, j) || isNb(i, j);
    const fs = w.fill.userData.style, rs = w.ring.userData.style;
    if (inBl) { fs.tc.copy(w.shade); fs.to = 1; set(rs, isSel(i, j) ? C_ACCENT : C_BLACK, 1); }
    else { set(fs, C_DIM, 0.15); set(rs, C_DIM, 0.15); }

    const g = gray[j][i];
    const gf = g.fill.userData.style, gr = g.ring.userData.style;
    if (!showObs) { gf.to = 0; gr.to = 0; gf.tc.copy(g.shade); gr.tc.setHex(C_BLACK); }
    else if (!sel || isSel(i, j)) { gf.tc.copy(g.shade); gf.to = 1; set(gr, isSel(i, j) ? C_ACCENT : C_BLACK, 1); }
    else { set(gf, C_DIM, 0.15); set(gr, C_DIM, 0.15); }
  }
}

/* ── interactions: click a site ────────────────────────────────────────── */
const pickables = [];
for (let j = 0; j < 3; j++) for (let i = 0; i < 3; i++) {
  const w = white[j][i];
  pickables.push(w.fill, w.ring);
  registerInteractive(w.fill, {
    title: `Hidden state x at site (${i + 1}, ${j + 1})`,
    tooltip: 'Show Markov blanket',
    body: 'Given its four lattice neighbours and its own observation y, this state is conditionally independent of every other variable in the field. That blanket is highlighted in blue; everything outside it is faded out.',
    onClick: () => { state.selected = [i, j]; updateStyle(); }
  });
  const g = gray[j][i];
  pickables.push(g.fill);
  registerInteractive(g.fill, {
    title: `Observation y at site (${i + 1}, ${j + 1})`,
    tooltip: 'Per-site observation',
    body: 'Each grey observation node attaches to exactly one hidden state through a single vertical edge. Evidence therefore enters the model one site at a time; observations are never linked to each other.'
  });
}

const _rc = new THREE.Raycaster();
const _pt = new THREE.Vector2();
renderer.domElement.addEventListener('click', (ev) => {
  const r = renderer.domElement.getBoundingClientRect();
  _pt.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  _pt.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
  _rc.setFromCamera(_pt, camera);
  const hits = _rc.intersectObjects(pickables, false);
  if (!hits.length) { state.selected = null; updateStyle(); }
});

/* ── UI wiring ─────────────────────────────────────────────────────────── */
const bLat = document.getElementById('lyLat');
const bObs = document.getElementById('lyObs');
const bFull = document.getElementById('lyFull');
const slider = document.getElementById('coupling');
const betaOut = document.getElementById('betaOut');

function setLayer(l) {
  state.layer = l;
  bLat.classList.toggle('active', l === 'lattice');
  bObs.classList.toggle('active', l === 'obs');
  bFull.classList.toggle('active', l === 'full');
  updateStyle();
}
bLat.addEventListener('click', () => setLayer('lattice'));
bObs.addEventListener('click', () => setLayer('obs'));
bFull.addEventListener('click', () => setLayer('full'));

slider.addEventListener('input', () => {
  betaTarget = parseFloat(slider.value);
  beta = betaTarget;
  betaOut.textContent = beta.toFixed(2);
  updateShading(); updateStyle();
});
document.getElementById('clearSel').addEventListener('click', () => {
  state.selected = null; updateStyle(); hidePopup();
});

/* ── guided tour ───────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Hidden state lattice', text: 'Only the white x nodes and their grid edges are shown: each site is joined to its four lattice neighbours, and the edges run off frame to signal an unbounded array.', layer: 'lattice', beta: 0 },
  { title: 'Per-site observations', text: 'Now only the vertical links appear: every grey y node hangs off exactly one white x node and touches nothing else, so evidence enters the model one site at a time.', layer: 'obs', beta: 0 },
  { title: 'Full MRF', text: 'Both layers together form the Markov random field. Click any white node to see its Markov blanket: four neighbours plus its own observation.', layer: 'full', beta: 0 },
  { title: 'Smoothness from coupling', text: 'Raising the coupling strength makes neighbouring white nodes take on similar shading while the grey observations stay fixed — pairwise potentials pull the field toward piecewise-constant labelings.', layer: 'full', beta: 0.85 }
];
let stepIdx = 2;
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

function goToStep(k) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, k));
  const s = STEPS[stepIdx];
  stepTitle.textContent = `${stepIdx + 1}. ${s.title}`;
  stepText.textContent = s.text;
  setLayer(s.layer);
  state.selected = null;
  betaTarget = s.beta;
  updateStyle();
}
document.getElementById('prevStep').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('nextStep').addEventListener('click', () => goToStep(stepIdx + 1));

/* ── per-frame updates: billboards, beta tween, colour lerp ────────────── */
let _t0 = performance.now();
function figTick() {
  requestAnimationFrame(figTick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _t0) / 1000); _t0 = now;

  for (const o of billboards) o.quaternion.copy(camera.quaternion);

  if (Math.abs(beta - betaTarget) > 1e-3) {
    beta += (betaTarget - beta) * Math.min(1, dt * 5);
    slider.value = beta.toFixed(2);
    betaOut.textContent = beta.toFixed(2);
    updateShading(); updateStyle();
  }

  const k = Math.min(1, dt * 10);
  for (const e of styled) {
    const m = e.mesh.material;
    m.color.lerp(e.tc, k);
    m.opacity += (e.to - m.opacity) * k;
    e.mesh.visible = m.opacity > 0.01;
  }
}
updateShading();
goToStep(2);
figTick();
// @FIGURE_CODE_END

